  insert into questions (chapter_id, type, category, source, difficulty, stem_md, options_json, answer_key_md, marks, family, explanation_md)
  values
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'When an electron moves from a lower energy shell to a higher energy shell, what is the underlying physical requirement?', '["The electron must emit a photon.","The electron must absorb a specific amount of energy.","The nucleus must decrease its proton count.","The atom must become an ion."]'::jsonb, 'B', 1, '8084c7d9a8ba', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'Which observation from Rutherford''s experiment suggested that most of the atom is empty space?', '["Most alpha particles passed straight through the foil.","Most alpha particles were deflected.","Gold foil melted during the experiment.","Electrons were emitted from the foil."]'::jsonb, 'A', 1, 'c90dfc3e3cfa', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An atom contains 17 protons and 17 electrons. Its net charge is:', '["+17","+34","-17","0"]'::jsonb, 'D', 1, 'a3dab8cb5f2e', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which particle contributes the least to the mass of an atom?', '["Proton","Neutron","Electron","Nucleus"]'::jsonb, 'C', 1, '6610de02456b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is it impossible to map the exact trajectory of an electron around the nucleus?', '["Electrons move too slowly to be tracked.","Electrons behave as quantum particles with probabilistic paths rather than fixed orbits.","The nucleus is too small to serve as a reference point.","Electrons have no mass."]'::jsonb, 'B', 1, '964d8b49f31b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which force is primarily responsible for keeping protons and neutrons bound together within the nucleus?', '["Gravitational force","Electromagnetic force","Strong nuclear force","Centripetal force"]'::jsonb, 'C', 1, 'e238ba4f8145', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which statement best supports the existence of a dense nucleus?', '["Alpha particles were strongly deflected.","Electrons have negative charge.","Atoms combine to form compounds.","Neutrons are neutral."]'::jsonb, 'A', 1, '7661301a3749', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which scientist discovered the electron?', '["Rutherford","Chadwick","Bohr","Thomson"]'::jsonb, 'D', 1, 'd083555951d9', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'If an atom undergoes a radioactive change that alters its proton number, what is the direct consequence?', '["The atom''s identity changes to a different element.","The atom becomes a molecule.","The number of electrons remains unchanged.","The mass of the atom remains identical."]'::jsonb, 'A', 1, 'c7a4851458cb', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'How does the energy level of an electron shell correlate with its distance from the nucleus?', '["Larger distance implies lower energy.","Distance has no relationship with energy.","Larger distance implies higher energy.","Distance is inversely proportional to the square of the energy."]'::jsonb, 'C', 1, 'dfddffb84a10', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'The atomic model is best described as:', '["A perfect replica of the atom.","A tool to aid our understanding of complex subatomic structure.","A set of unchangeable laws.","A physical scale model that shows the actual size of protons."]'::jsonb, 'B', 1, '0289445f9f28', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'If a nucleus loses a neutron but the number of protons remains the same, the atom becomes:', '["A different element.","A negatively charged ion.","A positively charged ion.","An isotope of the same element."]'::jsonb, 'D', 1, '32076f722dc3', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An atom''s identity is based on 8 protons. If you add 2 neutrons, it is still oxygen. Why?', '["Neutrons do not determine the element''s identity.","Protons determine the identity, and that number stayed 8.","The nucleus is too large to change.","The mass number is irrelevant."]'::jsonb, 'B', 1, '17b2dfb8ea1c', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'The second shell can accommodate a maximum of:', '["2 electrons","4 electrons","8 electrons","18 electrons"]'::jsonb, 'C', 1, '97a30545f48b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which atomic model first introduced the concept of quantized energy levels?', '["Dalton''s model","Thomson''s model","Rutherford''s model","Bohr''s model"]'::jsonb, 'D', 1, 'c72b27b42729', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'Which experiment led to the rejection of Thomson''s plum pudding model?', '["Gold foil experiment","Cathode ray experiment","Oil drop experiment","Radioactivity experiment"]'::jsonb, 'A', 1, 'fb3b3a51abb4', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'According to modern atomic theory, the exact position of an electron:', '["Can always be determined precisely","Is fixed in a circular orbit","Cannot be known with complete certainty","Is inside the nucleus"]'::jsonb, 'C', 1, '9868ed4b3d4b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'The discovery of the neutron was made by:', '["Dalton","Chadwick","Bohr","Rutherford"]'::jsonb, 'B', 1, '3bb380343087', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'When interpreting the relationship between a particle''s charge and its path in an electric field, we observe:', '["Neutral particles are deflected the most.","Oppositely charged particles deflect in opposite directions.","Both positive and negative particles move toward the same plate.","Only electrons can be deflected."]'::jsonb, 'B', 1, '98a986c9e4bd', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What happens to the average distance of an electron from the nucleus as the shell energy level increases?', '["It decreases.","It increases.","It remains the same.","It becomes zero."]'::jsonb, 'B', 1, 'ff94e7660f86', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'The nucleus occupies:', '["Most of the volume of the atom","Half of the atom","Entire atom","Very little space inside the atom"]'::jsonb, 'D', 1, '4e66376a2ff9', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'How would an electron react if exposed to a uniform electric field?', '["It would be attracted to the negative electrode.","It would be attracted to the positive electrode.","It would remain stationary.","It would only move if it were a proton."]'::jsonb, 'B', 1, 'a4c479080f70', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which scientist first proposed that atoms are indivisible particles?', '["Dalton","Thomson","Rutherford","Bohr"]'::jsonb, 'A', 1, '2e5645320365', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'In Thomson''s model, electrons were assumed to be:', '["Revolving around the nucleus","Embedded in a positively charged sphere","Located in fixed shells","Present inside neutrons"]'::jsonb, 'B', 1, '60528149c1c1', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'How does an alpha particle behave in a magnetic or electric field compared to an electron?', '["They behave identically because they are both subatomic.","The alpha particle deflects much less due to its significantly higher mass and positive charge.","The alpha particle is unaffected by electric fields.","The electron is deflected less because it is lighter."]'::jsonb, 'B', 1, 'f391f92f9b7d', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What is the structural role of neutrons in a nucleus containing multiple protons?', '["They act as a glue to overcome the electrostatic repulsion between positively charged protons.","They increase the volume of the atom.","They provide energy for the electrons.","They define the chemical properties of the element."]'::jsonb, 'A', 1, '5aa54f257a20', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is the concept of a "shell" as an energy level more accurate than the concept of an "orbit"?', '["Shells are physical rings made of matter.","Orbits are only for planets, not atoms.","Shells are bigger than orbits.","Orbits imply a fixed, predictable path, whereas shells define specific energy states where electrons exist based on probability."]'::jsonb, 'D', 1, 'fcffb25c5120', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why are electrons described as quantum particles?', '["Because they have a large mass.","Because they are found only in the nucleus.","Because they exhibit behavior that classical mechanics cannot explain.","Because they move in straight lines."]'::jsonb, 'C', 1, 'b1c2a2dae6f0', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An atom contains 18 electrons arranged as 2, 8, 8. The total number of protons is:', '["8","16","18","20"]'::jsonb, 'C', 1, 'f716c842aef5', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An atom has a nucleon number of 23 and an atomic number of 11. How many neutrons are in the nucleus?', '["11","12","23","34"]'::jsonb, 'B', 1, '7682910fc94e', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'How does the ''strong nuclear force'' overcome the electrostatic repulsion between protons in a high-atomic-number nucleus?', '["It acts at long ranges to pull protons toward the electron cloud.","It is an attractive force that dominates at extremely short distances, counteracting electrostatic repulsion.","It transforms protons into neutrons.","It is a gravitational effect generated by the nucleus mass."]'::jsonb, 'B', 1, 'd125ee369211', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'If an atom has a nucleon number (A) and an atomic number (Z), why does the loss of a neutron change the isotope but not the chemical identity?', '["Because chemical identity is governed solely by electron configuration, which is determined by proton count.","Because neutrons carry a positive charge.","Because neutrons have zero mass.","Because the nucleus expands."]'::jsonb, 'A', 1, '78d44cb81de7', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student says, "Rutherford''s model proved that electrons are present in the nucleus." Which fact directly disproves this statement?', '["Most α-particles passed through the foil.","Electrons were discovered before Rutherford''s experiment.","Rutherford proposed that electrons move around the nucleus.","Gold foil is a metal."]'::jsonb, 'C', 1, '0a724710553f', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which feature of the atom remained unchanged from Rutherford''s model to Bohr''s model?', '["Electrons carrying a positive charge","Electrons embedded in positive charge","Absence of nucleus","Presence of a central nucleus"]'::jsonb, 'D', 1, 'b780c1be40a4', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'If Rutherford had observed all α-particles passing straight through the foil without any deflection, he would most likely have concluded that:', '["Atoms contain no dense central region.","Positive charge is concentrated in the nucleus.","Electrons are negatively charged.","Bohr''s model is correct."]'::jsonb, 'A', 1, 'da071b01c648', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'If you have a nucleus with 20 protons and 20 neutrons, what happens to the electrostatic repulsion if one proton is added?', '["The repulsion decreases.","The atom becomes a gas.","The repulsion increases, requiring more neutrons for nuclear stability.","The number of electrons stays the same."]'::jsonb, 'C', 1, '46276d15a1a8', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is the shell model considered an "aid" rather than a photographic representation?', '["Because atoms are too small to have a structure.","Because it simplifies the complex quantum reality of electron distribution for educational clarity.","Because atoms do not have shells.","Because shells are only visible under high heat."]'::jsonb, 'B', 1, '33bc1e850b80', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Bohr''s model successfully explained hydrogen spectra because it assumed that electrons:', '["Have no mass.","Could possess any energy.","Remain inside the nucleus.","Occupy specific energy levels."]'::jsonb, 'D', 1, '403c7b9e9485', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An atom has atomic number Z and mass number A. Which expression represents the number of neutrons?', '["Z − A","A/Z","A − Z","Z + A"]'::jsonb, 'C', 1, '451251b69d75', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Dalton''s atomic theory could not explain isotopes because it assumed:', '["Atoms contain electrons.","Atoms of the same element are identical in mass.","Atoms contain nuclei.","Atoms are mostly empty space."]'::jsonb, 'B', 1, 'd1d9ee728846', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which conclusion can be drawn from the fact that α-particles are positively charged?', '["They are repelled by the positively charged nucleus.","They are attracted toward the nucleus.","They are neutral.","They contain electrons."]'::jsonb, 'A', 1, '07d8b6eeed67', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which statement would be impossible?', '["Two isotopes having different mass numbers","Two isotopes having different neutrons","Two isotopes having the same chemical properties","Two isotopes having different atomic numbers"]'::jsonb, 'D', 1, 'cbfedd626c5d', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Relative to a proton, the mass of an electron is approximately:', '["Equal","1/1836th","Double","10 times greater"]'::jsonb, 'B', 1, 'c1504b10be29', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'The existence of ions demonstrates that:', '["Atoms can gain or lose electrons.","Atoms can gain or lose protons easily.","Atomic number changes during chemical reactions.","Nuclei are unstable."]'::jsonb, 'A', 1, 'a53786e5fb9c', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why can we not map the "exact path" of an electron?', '["Because it isn''t moving.","Because the act of measuring its position affects its momentum.","Because electrons are too heavy.","Because the nucleus blocks our view."]'::jsonb, 'B', 1, '0376e1a7238f', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'How does the periodic table arrange elements based on atomic structure?', '["By mass, regardless of proton count.","By increasing atomic number.","By the number of neutrons.","By the total volume of the atom."]'::jsonb, 'B', 1, '059de6fa4b89', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'In an electric field, why does a neutron travel completely straight regardless of its velocity?', '["It is repelled by both plates equally.","It is moving too fast for the field to affect it.","Its mass is too large.","It lacks an electric charge, so it experiences no electrostatic force."]'::jsonb, 'D', 1, 'e2f65cdd4a94', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'In an atom, the "empty space" is:', '["The region occupied by the electron shells.","Where the nucleus is located.","A myth; there is no empty space.","Filled with protons."]'::jsonb, 'A', 1, '3e8dc3f0ab51', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'How does the energy requirement for removing an electron from the first shell compare to the third shell?', '["It is easier to remove from the first shell.","They are identical.","It is much harder to remove from the first shell because it is closer to the nucleus.","Electrons cannot be removed from the first shell."]'::jsonb, 'C', 1, '2f4682dae9d6', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'If a nucleus undergoes beta decay (a neutron turns into a proton), what happens to the atomic number?', '["It stays the same.","It increases by 1.","It decreases by 1.","The atom disappears."]'::jsonb, 'B', 1, 'a765315ecce9', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A teacher asks why Rutherford rejected Thomson''s model. A student replies, "Because some α-particles bounced back." Which assumption of Thomson''s model was challenged?', '["Presence of electrons","Uniform distribution of positive charge","Existence of isotopes","Presence of neutrons"]'::jsonb, 'B', 1, '184e86f7f098', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student claims that atoms of the same element must have identical masses. Which discovery proves the student wrong?', '["Electron","Energy levels","Proton","Isotopes"]'::jsonb, 'D', 1, '1086fdb7199c', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A neutral atom has an electronic configuration 2,8,7. If it gains one electron, the resulting particle will:', '["Lose a proton.","Become negatively charged.","Become neutral.","Become positively charged."]'::jsonb, 'B', 1, '42e45a6e501b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A particle contains 13 protons, 14 neutrons, and 10 electrons. Which statement is correct?', '["Mass number = 24","Charge = –3","Atomic number = 14","Charge = +3"]'::jsonb, 'D', 1, '31ae92dad493', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student compares Rutherford''s and Bohr''s models. Which feature is present in both?', '["Positive sphere with embedded electrons","Central nucleus","Neutrons in the nucleus","Quantized energy levels"]'::jsonb, 'B', 1, '929fa451a550', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student is asked which discovery directly contradicted Dalton''s idea of indivisible atoms. Which answer is most appropriate?', '["Discovery of the electron","Discovery of an isotope","Discovery of energy levels","Discovery of valency"]'::jsonb, 'A', 1, '7d9690180c24', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student notices that an electron jumps from the second shell to the fourth shell. According to Bohr''s theory, the electron must have:', '["Lost mass","Lost charge","Released energy","Absorbed energy"]'::jsonb, 'D', 1, 'b69c8f5aac78', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'When an electron emits a photon, it must:', '["Change into a proton.","Increase its velocity to infinity.","Move to a shell further from the nucleus.","Move to a shell closer to the nucleus."]'::jsonb, 'D', 1, 'dbbe35f085b5', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student is comparing Cl-35 and Cl⁻. Which statement correctly distinguishes them?', '["One differs in neutrons, the other differs in electrons.","Both differ in neutrons only.","Both differ in electrons only.","Both are isotopes."]'::jsonb, 'A', 1, 'f0c8a65b4304', null);
